  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Isocorydine, a close aporphine alkaloid with N-methyl and multiple methoxy groups, was detected in rat brain within 10 minutes of administration, demonstrating effective BBB crossing for this isoquinoline alkaloid class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Apomorphine, an aporphine alkaloid sharing the N-methylated isoquinoline core, readily crossed the BBB in rats with brain concentrations exceeding plasma levels, supporting CNS access for related alkaloids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Demethyleneberberine, a related isoquinoline alkaloid, reached 267.56 ng/g in rat brain after oral administration, showing meaningful brain exposure despite polar structural features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Tylocrebrine, a polycyclic alkaloid with multiple methoxy groups, showed rapid brain accumulation with an AUCbrain of 2.1 µg·h/mL in mice, supporting CNS access for this alkaloid family.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass. The query is a noscapine-type phthalideisoquinoline alkaloid. Multiple high-transfer analogues from the same isoquinoline/alkaloid family show direct brain penetration after systemic administration, and the physicochemical prior indicates favorable passive BBB properties. These converging lines of evidence support meaningful CNS access.",
  "evidence_gaps": [
    "No direct experimental brain/plasma or CSF data for the query molecule itself.",
    "Efflux transporter interactions, particularly P-gp, are not directly measured for the query.",
    "Lactone or methylenedioxy metabolism could alter systemic exposure, but this does not negate the strong transferable CNS-penetration evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

